import json
from collections import defaultdict
p='/app/benchmark/source_data.json'
data=json.load(open(p))
for k,v in data.items():
 print('\n',k, v.get('unit'))
 print('rows', len(v['data']))
 print(v['data'][:3])
# compute metrics
mmr=defaultdict(dict)
for r in data['maternal_mortality_timeseries']['data']:
 mmr[r['country']][r['year']]=r['mmr']
exp=defaultdict(dict)
for r in data['health_expenditure_gdp']['data']:
 exp[r['country']][r['year']]=r['health_exp_pct_gdp']
cover={r['country']:r['skilled_birth_attendant_pct'] for r in data['midwife_coverage']['data'] if r['period']=='2018-2021'}
gap=defaultdict(dict)
for r in data['rural_urban_mmr_gap']['data']:
 gap[r['country']][r['setting']]=r['mmr']
for c in sorted(mmr):
 print(c, 'mmr', mmr[c][2005], mmr[c][2021], 'decline', mmr[c][2005]-mmr[c][2021], 'exp', exp[c][2005], exp[c][2021], 'cov', cover[c], 'gap', gap[c]['rural']-gap[c]['urban'])
